  const [ID, setID] = useState([])
  const [name, setName] = useState([])


const createdevice = () => {
  Axios.get("http://localhost:3001/createdevice",{
    identifier:ID,
    name:name,
    status:false
  })
.then(res => {
})
}

  return (
    <>

      <div className="form">
        <h1>Register New Device</h1>
        <form>
          {/* <label for="name">Name:</label> */}
          <input
            /* ref={id_value} */
